alter table public.students add column if not exists proficiency_level text not null default 'unassessed'
  check(proficiency_level in ('unassessed','new','beginner','intermediate','advanced'));

create or replace function public.save_student_profile(target_academy uuid,target_student uuid,student_name text,
  age_years integer,guardian_name text,guardian_email text,guardian_phone text,batch_ids uuid[],student_level text)
returns uuid language plpgsql security definer set search_path='' as $$
begin
  if not coach_private.owns_academy(target_academy) then raise exception 'Student unavailable' using errcode='42501'; end if;
  if student_level is null or student_level not in ('unassessed','new','beginner','intermediate','advanced') then
    raise exception 'Choose a learning level' using errcode='22023';
  end if;
  perform public.save_student(target_academy,target_student,student_name,age_years,guardian_name,guardian_email,guardian_phone,batch_ids);
  update public.students set proficiency_level=student_level where id=target_student and academy_id=target_academy;
  return target_student;
end $$;
revoke all on function public.save_student_profile(uuid,uuid,text,integer,text,text,text,uuid[],text) from public,anon;
grant execute on function public.save_student_profile(uuid,uuid,text,integer,text,text,text,uuid[],text) to authenticated;

create or replace function public.add_batch_students(target_academy uuid,target_batch uuid,student_ids uuid[])
returns integer language plpgsql security definer set search_path='' as $$
declare child uuid; local_day date; added integer:=0; changed integer;
begin
  if not coach_private.owns_academy(target_academy) then raise exception 'Batch unavailable' using errcode='42501'; end if;
  perform 1 from public.batches where id=target_batch and academy_id=target_academy and archived_at is null for update;
  if not found then raise exception 'Batch unavailable' using errcode='42501'; end if;
  if student_ids is null or cardinality(student_ids) not between 1 and 500 or array_position(student_ids,null) is not null then
    raise exception 'Choose students' using errcode='22023';
  end if;
  select (now() at time zone timezone)::date into local_day from public.academies where id=target_academy;
  foreach child in array student_ids loop
    if not exists(select 1 from public.students where id=child and academy_id=target_academy and archived_at is null)
      or exists(select 1 from public.enrolments where academy_id=target_academy and student_id=child and batch_id=target_batch and ends_on is not null) then
      raise exception 'Review selected students and enrolment dates' using errcode='22023';
    end if;
    insert into public.enrolments(academy_id,student_id,batch_id,starts_on)
      values(target_academy,child,target_batch,local_day) on conflict(academy_id,student_id,batch_id) do nothing;
    get diagnostics changed=row_count; added:=added+changed;
  end loop;
  return added;
end $$;

-- The coach records a receipt from a student's row. Create the trusted monthly
-- charge only when required, in the same transaction as the receipt. An invalid
-- receipt rolls both back; exact retries are checked before current roster state.
create or replace function public.collect_student_fee(target_academy uuid,target_enrolment uuid,month_start date,
  expected_invoice uuid,expected_fee bigint,payment_request uuid,payment_amount bigint,payment_date date,payment_method text,payment_reference text)
returns uuid language plpgsql security definer set search_path='' as $$
declare invoice public.fee_invoices; prior public.fee_payments; invoice_id uuid;
begin
  if not coach_private.owns_academy(target_academy) then raise exception 'Fee unavailable' using errcode='42501'; end if;
  perform 1 from public.academies where id=target_academy for update;
  select * into prior from public.fee_payments where request_id=payment_request;
  if prior.id is not null then
    select * into invoice from public.fee_invoices where id=prior.invoice_id;
    if prior.academy_id<>target_academy or invoice.enrolment_id is distinct from target_enrolment
      or invoice.billing_month is distinct from month_start or invoice.amount_paise is distinct from expected_fee
      or (expected_invoice is not null and expected_invoice<>invoice.id) then
      raise exception 'Request details changed' using errcode='22023';
    end if;
    perform public.record_manual_fee_payment(target_academy,invoice.id,payment_request,payment_amount,payment_date,payment_method,payment_reference);
    return invoice.id;
  end if;
  select * into invoice from public.fee_invoices where academy_id=target_academy and enrolment_id=target_enrolment
    and billing_month=month_start and voided_at is null;
  if invoice.id is distinct from expected_invoice then raise exception 'Fee changed; refresh' using errcode='40001'; end if;
  if invoice.id is null then
    invoice_id:=public.create_fee_invoice(target_academy,payment_request,target_enrolment,month_start,
      (month_start+interval '1 month'-interval '1 day')::date,expected_fee);
  else
    if invoice.amount_paise is distinct from expected_fee then raise exception 'Fee changed; refresh' using errcode='40001'; end if;
    invoice_id:=invoice.id;
  end if;
  perform public.record_manual_fee_payment(target_academy,invoice_id,payment_request,payment_amount,payment_date,payment_method,payment_reference);
  return invoice_id;
end $$;
revoke all on function public.add_batch_students(uuid,uuid,uuid[]),
  public.collect_student_fee(uuid,uuid,date,uuid,bigint,uuid,bigint,date,text,text) from public,anon;
grant execute on function public.add_batch_students(uuid,uuid,uuid[]),
  public.collect_student_fee(uuid,uuid,date,uuid,bigint,uuid,bigint,date,text,text) to authenticated;
insert into coach_private.schema_migrations(version) values('202611150007') on conflict do nothing;
notify pgrst,'reload schema';
commit;

-- SOURCE: 202611150008_private_photos.sql
begin;
do $$ begin
  if not exists(select 1 from coach_private.schema_migrations where version='202611150007') then raise exception 'Apply update007 first'; end if;
end $$;
create table if not exists public.coach_photos (
  kind text not null check(kind in ('student','observation')), entity_id uuid not null,
  academy_id uuid not null references public.academies(id),
  student_id uuid, observation_id uuid, object_path text not null unique,
  object_id uuid not null references storage.objects(id),
  updated_by uuid not null references auth.users(id), updated_at timestamptz not null default now(),
  primary key(kind,entity_id),
  foreign key(student_id,academy_id) references public.students(id,academy_id),
  foreign key(observation_id,academy_id) references public.observations(id,academy_id),
  check((kind='student' and student_id is not null and student_id=entity_id and observation_id is null)
    or (kind='observation' and observation_id is not null and observation_id=entity_id and student_id is null))
);
alter table public.coach_photos enable row level security;
revoke all on public.coach_photos from public,anon,authenticated;
grant select on public.coach_photos to authenticated;
grant all on public.coach_photos to service_role;
drop policy if exists academy_access on public.coach_photos;
create policy academy_access on public.coach_photos for select to authenticated using(coach_private.owns_academy(academy_id));
create index if not exists coach_photos_academy_idx on public.coach_photos(academy_id);

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
  values('parentplus-coach-photos','parentplus-coach-photos',false,5242880,array['image/jpeg','image/png','image/webp'])
  on conflict(id) do update set public=false,file_size_limit=5242880,allowed_mime_types=excluded.allowed_mime_types;

create or replace function coach_private.photo_path_owned(path text, editable boolean)
returns boolean language plpgsql stable security definer set search_path='' as $$
declare parts text[]; academy uuid; entity uuid;
begin
  parts:=string_to_array(path,'/');
  if cardinality(parts)<>4 or parts[1] !~* '^[0-9a-f-]{36}$' or parts[3] !~* '^[0-9a-f-]{36}$'
    or parts[4] !~* '^[0-9a-f-]{36}[.](jpg|png|webp)$' then return false; end if;
  academy:=parts[1]::uuid; entity:=parts[3]::uuid;
  if not coach_private.owns_academy(academy) then return false; end if;
  if parts[2]='student' then return exists(select 1 from public.students where id=entity and academy_id=academy and (not editable or archived_at is null)); end if;
  if parts[2]='observation' then return exists(select 1 from public.observations where id=entity and academy_id=academy and (not editable or status='draft')); end if;
  return false;
exception when invalid_text_representation then return false;
end $$;
revoke all on function coach_private.photo_path_owned(text,boolean) from public,anon;
grant execute on function coach_private.photo_path_owned(text,boolean) to authenticated;

drop policy if exists coach_photo_insert on storage.objects;
create policy coach_photo_insert on storage.objects for insert to authenticated
  with check(bucket_id='parentplus-coach-photos' and coach_private.photo_path_owned(name,true));
drop policy if exists coach_photo_read on storage.objects;
create policy coach_photo_read on storage.objects for select to authenticated
  using(bucket_id='parentplus-coach-photos' and coach_private.photo_path_owned(name,false));
-- Objects are immutable. Replacements get a fresh random name; deletion is
-- allowed only once metadata no longer references an object, protecting a
-- committed upload whose response was lost.
drop policy if exists coach_photo_delete on storage.objects;
create policy coach_photo_delete on storage.objects for delete to authenticated
  using(bucket_id='parentplus-coach-photos' and coach_private.photo_path_owned(name,false)
    and not exists(select 1 from public.coach_photos p where p.object_path=name));

create or replace function public.attach_coach_photo(target_academy uuid,entity_kind text,target_entity uuid,target_path text,expected_path text)
returns text language plpgsql security definer set search_path='' as $$
declare existing public.coach_photos; state text; stored_object uuid;
begin
  if not coach_private.owns_academy(target_academy) then raise exception 'Photo unavailable' using errcode='42501'; end if;
  if entity_kind='student' then
    select case when archived_at is null then 'active' else 'archived' end into state from public.students where id=target_entity and academy_id=target_academy for update;
  elsif entity_kind='observation' then
    select status into state from public.observations where id=target_entity and academy_id=target_academy for update;
  end if;
  if state is null then raise exception 'Photo unavailable' using errcode='42501'; end if;
  select * into existing from public.coach_photos where kind=entity_kind and entity_id=target_entity;
  if existing.object_path is not distinct from target_path then return target_path; end if;
  if state in ('recorded','archived') then raise exception 'Recorded photos are fixed' using errcode='22023'; end if;
  if existing.object_path is distinct from expected_path then raise exception 'Photo changed; refresh' using errcode='40001'; end if;
  if target_path is null then
    delete from public.coach_photos where kind=entity_kind and entity_id=target_entity;
    return null;
  end if;
  if target_path not like target_academy::text||'/'||entity_kind||'/'||target_entity::text||'/%'
    or not coach_private.photo_path_owned(target_path,true)
    or not exists(select 1 from storage.objects where bucket_id='parentplus-coach-photos' and name=target_path
      and (metadata->>'size')::bigint between 1 and 5242880 and metadata->>'mimetype' in ('image/jpeg','image/png','image/webp')) then
    raise exception 'Upload a supported photo first' using errcode='22023';
  end if;
  select id into stored_object from storage.objects where bucket_id='parentplus-coach-photos' and name=target_path for key share;
  if stored_object is null then raise exception 'Photo upload unavailable' using errcode='22023'; end if;
  insert into public.coach_photos(kind,entity_id,academy_id,student_id,observation_id,object_path,object_id,updated_by)
    values(entity_kind,target_entity,target_academy,case when entity_kind='student' then target_entity end,
      case when entity_kind='observation' then target_entity end,target_path,stored_object,auth.uid())
    on conflict(kind,entity_id) do update set object_path=excluded.object_path,object_id=excluded.object_id,updated_by=excluded.updated_by,updated_at=now();
  return target_path;
end $$;
revoke all on function public.attach_coach_photo(uuid,text,uuid,text,text) from public,anon;
grant execute on function public.attach_coach_photo(uuid,text,uuid,text,text) to authenticated;
insert into coach_private.schema_migrations(version) values('202611150008') on conflict do nothing;
notify pgrst,'reload schema';
commit;

-- SOURCE: 202611150009_roster_scan.sql
begin;
do $$ begin
  if not exists(select 1 from coach_private.schema_migrations where version='202611150008') then raise exception 'Apply update008 first'; end if;
end $$;
create table if not exists coach_private.roster_scan_usage (
  academy_id uuid not null references public.academies(id), day date not null,
  attempts integer not null check(attempts between 1 and 10), last_attempt timestamptz not null,
  primary key(academy_id,day)
);
create table if not exists coach_private.roster_imports (
  request_id uuid primary key, academy_id uuid not null references public.academies(id),
  payload jsonb not null, student_ids uuid[] not null, created_at timestamptz not null default now()
);
revoke all on coach_private.roster_scan_usage,coach_private.roster_imports from public,anon,authenticated;

create or replace function public.reserve_roster_scan(target_academy uuid)
returns void language plpgsql security definer set search_path='' as $$
declare used coach_private.roster_scan_usage; utc_day date:=(now() at time zone 'UTC')::date;
begin
  perform 1 from public.academies where id=target_academy for update;
  if not found then raise exception 'Academy unavailable' using errcode='42501'; end if;
  select * into used from coach_private.roster_scan_usage where academy_id=target_academy and day=utc_day;
  if used.attempts>=10 or used.last_attempt>now()-interval '10 seconds' then raise exception 'Scan limit reached' using errcode='P0001'; end if;
  insert into coach_private.roster_scan_usage(academy_id,day,attempts,last_attempt) values(target_academy,utc_day,1,now())
    on conflict(academy_id,day) do update set attempts=coach_private.roster_scan_usage.attempts+1,last_attempt=now();
end $$;
revoke all on function public.reserve_roster_scan(uuid) from public,anon,authenticated;
grant execute on function public.reserve_roster_scan(uuid) to service_role;

create or replace function public.import_roster_scan(target_academy uuid,target_batch uuid,import_request uuid,reviewed_students jsonb)
returns uuid[] language plpgsql security definer set search_path='' as $$
declare previous coach_private.roster_imports; body jsonb; item jsonb; student uuid; result uuid[]:='{}'; batches uuid[];
begin
  if not coach_private.owns_academy(target_academy) then raise exception 'Academy unavailable' using errcode='42501'; end if;
  perform 1 from public.academies where id=target_academy for update;
  body:=jsonb_build_object('batch',target_batch,'students',reviewed_students);
  select * into previous from coach_private.roster_imports where request_id=import_request;
  if previous.request_id is not null then
    if previous.academy_id<>target_academy or previous.payload is distinct from body then raise exception 'Import request changed' using errcode='22023'; end if;
    return previous.student_ids;
  end if;
  if import_request is null or jsonb_typeof(reviewed_students) is distinct from 'array' or jsonb_array_length(reviewed_students) not between 1 and 50 or length(reviewed_students::text)>100000 then
    raise exception 'Review 1 to 50 students' using errcode='22023';
  end if;
  if target_batch is not null and not exists(select 1 from public.batches where id=target_batch and academy_id=target_academy and archived_at is null) then
    raise exception 'Batch unavailable' using errcode='42501';
  end if;
  batches:=case when target_batch is null then '{}'::uuid[] else array[target_batch] end;
  for item in select * from jsonb_array_elements(reviewed_students) loop
    student:=(item->>'id')::uuid;
    if student is null or student=any(result) then raise exception 'Review duplicate student rows' using errcode='22023'; end if;
    if item->>'mode'='existing' then
      if not exists(select 1 from public.students where id=student and academy_id=target_academy and archived_at is null) then raise exception 'Student unavailable' using errcode='42501'; end if;
      if target_batch is not null then perform public.add_batch_students(target_academy,target_batch,array[student]); end if;
    elsif item->>'mode'='new' then
      if exists(select 1 from public.students where id=student)
        or exists(select 1 from public.students where academy_id=target_academy and lower(trim(regexp_replace(name,'\s+',' ','g')))=lower(trim(regexp_replace(item->>'name','\s+',' ','g')))) then
        raise exception 'A student with this name exists; review the existing profile' using errcode='22023';
      end if;
      perform public.save_student_profile(target_academy,student,item->>'name',nullif(item->>'age','')::integer,
        coalesce(item->>'guardian',''),coalesce(item->>'email',''),coalesce(item->>'phone',''),batches,coalesce(item->>'proficiency','unassessed'));
    else raise exception 'Review the student action' using errcode='22023'; end if;
    result:=array_append(result,student);
  end loop;
  insert into coach_private.roster_imports(request_id,academy_id,payload,student_ids) values(import_request,target_academy,body,result);
  return result;
end $$;
revoke all on function public.import_roster_scan(uuid,uuid,uuid,jsonb) from public,anon;
grant execute on function public.import_roster_scan(uuid,uuid,uuid,jsonb) to authenticated;
insert into coach_private.schema_migrations(version) values('202611150009') on conflict do nothing;
notify pgrst,'reload schema';
commit;

-- SOURCE: 202611150010_vision_monthly_limit.sql
begin;
do $$ begin
  if not exists(select 1 from coach_private.schema_migrations where version='202611150009') then raise exception 'Apply update009 first'; end if;
end $$;
create table if not exists coach_private.vision_scan_months (
  month date primary key check(extract(day from month)=1),
  attempts integer not null check(attempts between 1 and 900)
);
revoke all on coach_private.vision_scan_months from public,anon,authenticated;
create or replace function public.reserve_vision_roster_scan(target_academy uuid)
returns void language plpgsql security definer set search_path='' as $$
declare used integer; utc_month date:=date_trunc('month',now() at time zone 'UTC')::date;
begin
  -- One shared budget across academies. Reserve before the external OCR call;
  -- failed/unknown provider outcomes remain counted, so retries cannot overspend.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('parentplus-vision-'||utc_month::text,0));
  select attempts into used from coach_private.vision_scan_months where month=utc_month;
  if coalesce(used,0)>=900 then raise exception 'Monthly scan allowance reached' using errcode='P0002'; end if;
  perform public.reserve_roster_scan(target_academy);
  insert into coach_private.vision_scan_months(month,attempts) values(utc_month,1)
    on conflict(month) do update set attempts=coach_private.vision_scan_months.attempts+1;
end $$;
revoke all on function public.reserve_vision_roster_scan(uuid) from public,anon,authenticated;
grant execute on function public.reserve_vision_roster_scan(uuid) to service_role;
insert into coach_private.schema_migrations(version) values('202611150010') on conflict do nothing;
notify pgrst,'reload schema';
commit;
